import DuckDB
import Foundation

/// Process-wide serialization guard for DuckDB native library initialization.
///
/// The DuckDB C++ library (loaded via duckdb-swift) contains global initialization
/// state — memory allocators, extension registries, and thread-local storage setup —
/// that is not thread-safe when called concurrently. Simultaneous `Database(store:)`
/// calls from multiple Swift actors or threads (e.g., parallel test suites) race on
/// this global state and produce SIGSEGV (Signal 11).
///
/// This lock serializes every `Database(store:)` call process-wide. The locked
/// section is microseconds — it only wraps the native `duckdb_open` call, not the
/// subsequent schema setup — so the performance impact is negligible.
///
/// All three DuckDB actor inits (`DuckDBStorageActor`, `DuckDBCommitmentStore`,
/// `DuckDBContextCache`) must call `DuckDBInit.openDatabase(store:)` instead of
/// calling `Database(store:)` directly.
///
/// - Note: This is NOT a guard for Connection or query operations; those are already
///   actor-isolated and never shared across actors.
enum DuckDBInit {
    private static let lock = NSLock()

    /// Opens a DuckDB database under a process-wide lock to prevent concurrent
    /// native library initialization from racing on global state.
    ///
    /// File-backed databases are hardened to 0600 (owner read+write only) on every
    /// open. DuckDB OSS has no built-in at-rest encryption; OS file permissions are
    /// the primary access-control layer. For full encryption at rest, enable FileVault
    /// (System Settings › Privacy & Security › FileVault).
    ///
    /// - Parameter store: The DuckDB store descriptor (`.inMemory` or `.file(at:)`).
    /// - Returns: An open `Database` instance.
    /// - Throws: Rethrows any `Database` initializer error or file-permission error.
    static func openDatabase(store: Database.Store) throws -> Database {
        lock.lock()
        defer { lock.unlock() }
        let database = try Database(store: store)
        if case let .file(url) = store {
            try FileManager.default.setAttributes(
                [.posixPermissions: 0o600 as NSNumber],
                ofItemAtPath: url.path
            )
        }
        return database
    }
}

