import Foundation

/// Errors produced by the storage subsystem.
public enum StorageError: Error, Sendable, UserFacingError {
    /// No recording was found for the given identifier.
    case recordingNotFound(id: RecordingID)

    /// A write operation failed, optionally wrapping the underlying system error.
    case writeFailed(underlying: (any Error & Sendable)?)

    /// A read or decode operation failed, optionally wrapping the underlying error.
    case readFailed(underlying: (any Error & Sendable)?)

    /// An unauthorized DDL statement was executed.
    case unauthorizedDDL

    /// The provided file is invalid and cannot be persisted.
    case invalidFile(reason: String)

    /// A delete operation failed.
    case deleteFailed(id: RecordingID, underlying: (any Error & Sendable)?)

    /// An audio export operation failed.
    case exportFailed(underlying: (any Error & Sendable)?)

    /// A schema or data migration failed.
    case migrationFailed(underlying: (any Error & Sendable)?)

    /// A search operation failed.
    case searchFailed(underlying: (any Error & Sendable)?)

    // MARK: - UserFacingError

    public var userMessage: String {
        switch self {
        case .recordingNotFound:
            "Recording not found. It may have been deleted."
        case .writeFailed:
            "Failed to save data. Please check available disk space."
        case .readFailed:
            "Failed to read data. The database may be corrupted."
        case .unauthorizedDDL:
            "Unauthorized DDL statement."
        case let .invalidFile(reason):
            "Invalid file: \(reason)"
        case .deleteFailed:
            "Failed to delete recording."
        case .exportFailed:
            "Export failed. Please try again."
        case .migrationFailed:
            "Database migration failed. Contact support if this persists."
        case .searchFailed:
            "Search failed. Please try again."
        }
    }

    public var debugDescription: String {
        switch self {
        case let .recordingNotFound(id):
            "StorageError.recordingNotFound(id: \(id))"
        case let .writeFailed(underlying):
            "StorageError.writeFailed(underlying: \(String(describing: underlying)))"
        case let .readFailed(underlying):
            "StorageError.readFailed(underlying: \(String(describing: underlying)))"
        case .unauthorizedDDL:
            "StorageError.unauthorizedDDL"
        case let .invalidFile(reason):
            "StorageError.invalidFile(reason: \(reason))"
        case let .deleteFailed(id, underlying):
            "StorageError.deleteFailed(id: \(id), underlying: \(String(describing: underlying)))"
        case let .exportFailed(underlying):
            "StorageError.exportFailed(underlying: \(String(describing: underlying)))"
        case let .migrationFailed(underlying):
            "StorageError.migrationFailed(underlying: \(String(describing: underlying)))"
        case let .searchFailed(underlying):
            "StorageError.searchFailed(underlying: \(String(describing: underlying)))"
        }
    }
}

import AppKit
import AudioInfrastructure
import Business
import Domain
import Foundation
import MLInfrastructure
import OSLog
import Presentation
import Utilities
import RecordPro

// MARK: - Builder Methods

@MainActor
extension AppAssembler {

    // MARK: - Storage

    // swiftlint:disable:next function_body_length
    func buildStorage() async -> (reader: DuckDBReaderActor, writer: DuckDBWriterActor) {
        let isTest = ProcessInfo.processInfo.environment["XCTestConfigurationFilePath"] != nil
            || ProcessInfo.processInfo.processName.lowercased().contains("test")
            || ProcessInfo.processInfo.processName.lowercased().contains("xctest")

        let reader: DuckDBReaderActor
        let writer: DuckDBWriterActor
        do {
            let r = try await Task.detached {
                try isTest ? DuckDBReaderActor(databasePath: nil) : DuckDBReaderActor()
            }.value
            let db = await r.database
            let w = try await Task.detached {
                try DuckDBWriterActor(database: db)
            }.value
            reader = r
            writer = w
            if !isTest {
                let server = DuckDBCommandServer(storage: writer)
                commandServer = server
                taskBag.add(Task { await server.start() })
            }
        } catch {
            let errDesc = String(reflecting: error)
            logger
                .critical(
                    "DuckDB initialization failed: \(errDesc, privacy: .public) — falling back to in-memory storage",
                )
            do {
                let r = try await Task.detached {
                    try DuckDBReaderActor(databasePath: nil)
                }.value
                let db = await r.database
                let w = try await Task.detached {
                    try DuckDBWriterActor(database: db)
                }.value
                reader = r
                writer = w
                await showFatalAlert(error: error)
            } catch let fallbackError {
                let fbDesc = String(reflecting: fallbackError)
                logger
                    .critical(
                        "DuckDB fallback also failed: \(fbDesc, privacy: .public) — terminating via NSApp.terminate",
                    )
                await showFatalAlert(error: fallbackError)
                // Wait indefinitely because the alert terminates the app
                do { try await Task.sleep(nanoseconds: 10_000_000_000) } catch {}
                // Application will terminate from the alert, so we just return dummy instances or exit safely
                exit(1)
            }
        }

        // DuckDB is single-writer-per-file. Each actor owns an independent file:
        //   therecord.duckdb     → DuckDBStorageActor   (recordings + segments)
        //   commitments.duckdb → DuckDBCommitmentStore (commitments)
        let commitmentStore: DuckDBCommitmentStore?
        do {
            commitmentStore = try await Task.detached {
                if isTest {
                    return try DuckDBCommitmentStore(databasePath: nil)
                } else {
                    let dbDir = Directories.appSupport
                    try Directories.ensureDirectory(at: dbDir)
                    let dbURL = dbDir.appendingPathComponent(AppConstants.Paths.commitmentsDatabaseFileName)
                    return try DuckDBCommitmentStore(databasePath: dbURL)
                }
            }.value
        } catch {
            let errDesc = String(reflecting: error)
            // swiftlint:disable:next log_localized_description_at_error
            logger.error("Failed to init DuckDBCommitmentStore: \(errDesc, privacy: .public)")
            commitmentStore = nil
        }

        trackCommitmentsUseCase = commitmentStore.map { TrackCommitmentsUseCase(store: $0) }
        return (reader, writer)
    }

    /// Shows a fatal database-error alert, activates an existing instance if found,
    /// and terminates the app. Extracted to deduplicate the two identical alert blocks
    /// in `buildStorage`.
    @MainActor
    private func showFatalAlert(error: any Error) {
        let alert = NSAlert()
        alert.messageText = "THE RECORD could not start"
        // swiftlint:disable:next line_length
        alert.informativeText = "Failed to initialise the database: \(error.localizedDescription). If THE RECORD is already running, quit it and try again."
        alert.alertStyle = .warning
        alert.addButton(withTitle: "OK")
        alert.runModal()
        if let existing = NSRunningApplication.runningApplications(
            withBundleIdentifier: AppConstants.Bundle.identifier,
        ).first(where: { $0 != .current }) {
            existing.activate()
        }
        NSApp.terminate(nil)
    }

    // MARK: - Engine

    func buildEngine(
        config: AppConfig,
        fallbackTrack: TrackCommitmentsUseCase,
        alignment: (any AlignmentUseCase)? = nil,
        // swiftlint:disable:next large_tuple
    ) -> (TrackCommitmentsUseCase, TheRecordEngine, ContextSuggestionsViewModel, QueryContextUseCase) {
        let classifyUseCase = ClassifySegmentUseCase(classifier: OnDeviceNLPPlugin())
        let providers = buildMCPProviders(config: config)
        let queryContext = QueryContextUseCase()
        let engine = TheRecordEngine(
            classify: classifyUseCase,
            track: fallbackTrack,
            query: queryContext,
            providers: providers,
            alignment: alignment,
        )
        let suggestionsVM = ContextSuggestionsViewModel()
        return (fallbackTrack, engine, suggestionsVM, queryContext)
    }

    func buildMCPProviders(config: AppConfig) -> [any ContextProvider] {
        guard config.mcpConsentGranted else { return [] }

        // Try to create a context cache for semantic caching of query results.
        // If cache initialization fails, providers will work without caching.
        let contextCache: DuckDBContextCache?
        do {
            contextCache = try DuckDBContextCache(databasePath: nil)
        } catch {
            let errDesc = String(reflecting: error)
            logger.warning("Failed to initialize context cache: \(errDesc, privacy: .public)")
            contextCache = nil
        }

        // Migrate Keychain accessibility for existing credentials (no-op on clean install).
        let credentialStore = KeychainCredentialStore()
        try? credentialStore.migrateAccessibilityIfNeeded()

        var providers: [any ContextProvider] = []

        // Generic MCP endpoint providers (configured via mcpEndpoints).
        for endpoint in config.mcpEndpoints {
            let isLocal = endpoint.url.host == "localhost" || endpoint.url.host == "127.0.0.1"
            guard endpoint.url.scheme == "https" || isLocal else { continue }
            let provider = GenericMCPProvider(endpoint: endpoint.url, providerID: endpoint.providerID)
            providers.append(provider)
        }

        // Notion provider: constructed when the user has enabled the Notion integration.
        if config.notionEnabled {
            providers.append(NotionProvider(credentialStore: credentialStore))
        }

        // Obsidian provider: constructed when the user has configured a vault path.
        if let vaultPath = config.obsidianVaultPath, !vaultPath.isEmpty {
            providers.append(ObsidianProvider(vaultPath: URL(fileURLWithPath: vaultPath)))
        }

        // Wrap every provider in the caching layer when a cache is available.
        guard let cache = contextCache else { return providers }
        let cacheConfig = config.contextCache
        return providers.map { provider in
            CachingContextProvider(
                inner: provider,
                cache: cache,
                ttlSeconds: cacheConfig.exactTTLSeconds,
                semanticTTLSeconds: cacheConfig.semanticTTLSeconds,
                semanticThreshold: cacheConfig.semanticThreshold,
                maxEntries: cacheConfig.maxEntries,
            )
        }
    }

    // MARK: - Library VM

    func buildLibraryVM(
        reader: DuckDBReaderActor,
        writer: DuckDBWriterActor,
    ) -> (MeetingLibraryViewModel, Task<Void, Never>) {
        let libVM = MeetingLibraryViewModel(storage: reader)
        let migrationTask = Task<Void, Never> {
            do {
                let migrated = try await JSONMigrationHelper.migrate(
                    from: Directories.appSupport, reader: reader, writer: writer,
                )
                if migrated > 0 { logger.info("Migrated \(migrated, privacy: .public) recordings to DuckDB") }
            } catch {
                let errDesc = String(reflecting: error)
                logger.error("Migration failed: \(errDesc, privacy: .public)")
                await MainActor.run { libVM.errorMessage = "Migration failed: \(error.localizedDescription)" }
            }
        }
        return (libVM, migrationTask)
    }

    // MARK: - MenuBar VM

    // sequential setup — extraction would harm readability
    // swiftlint:disable:next function_parameter_count
    func buildMenuBarVM(
        reader: DuckDBReaderActor,
        writer: DuckDBWriterActor,
        engine: TheRecordEngine,
        suggestionsVM: ContextSuggestionsViewModel,
        migrationTask: Task<Void, Never>,
        config: AppConfig,
        queryContext: QueryContextUseCase,
        enableCoreAudioListeners: Bool = true,
    ) -> MenuBarViewModel {
        let audio = AudioSubAssembler().build(
            reader: reader, writer: writer, config: config, queryContext: queryContext,
        )
        let transcription = TranscriptionSubAssembler().build(
            reader: reader, writer: writer, audioCapture: audio.audioCapture, config: config,
        )
        transcriptionBuilt = transcription
        let audioDetector = AudioSessionDetector(
            selfRecordingProvider: audio.audioCapture,
            autoListen: enableCoreAudioListeners,
        )
        let eventKit = EventKitPlugin()
        let meetingDetector = CalendarAwareMeetingDetector(
            calendar: eventKit,
            audioDetector: audioDetector,
        )
        let pipelineCoordinator = PipelineCoordinator(
            cleanupTranscribe: transcription.cleanupUseCase,
            diarizeMeeting: transcription.diarizeUseCase,
            summarizeMeeting: transcription.summarizeUseCase,
            primaryEngine: transcription.primaryEngine,
            archivePassEnabled: config.transcription.archivePassEnabled,
        )
        Task {
            for await notification in NotificationCenter.default.notifications(named: .archivePassEnabledChanged) {
                guard let enabled = notification.userInfo?["enabled"] as? Bool else { continue }
                await pipelineCoordinator.updateArchivePassEnabled(enabled)
            }
        }
        var deps = MenuBarViewModel.Dependencies(
            startRecording: audio.startUseCase,
            stopAndTranscribe: transcription.stopUseCase,
            pipelineCoordinator: pipelineCoordinator,
            deleteRecording: DeleteRecordingUseCase(storage: writer),
            searchRecordings: SearchRecordingsUseCase(storage: reader),
            autoCleanup: audio.autoCleanup,
            exportAudio: ExportAudioUseCase(storage: reader, exportEngine: AVFoundationExporter()),
            migrationTask: migrationTask,
            engine: engine,
            contextSuggestionsVM: suggestionsVM,
            streamingTranscription: transcription.streamingUseCase,
            liveTranscriptionVM: transcription.liveTranscriptionVM,
            waveformVM: audio.waveformVM,
            liveTranslation: transcription.liveTranslateUseCase,
            listUpcomingMeetings: ListUpcomingMeetingsUseCase(calendar: eventKit),
            micAECProcessor: audio.aecProcessor,
            sleepAssertionService: IOKitSleepAssertionService(),
        )
        // epic-28 / task-003: AEC toggle + cleaned-WAV sink wiring
        deps.cleanedAudioSinkFactory = audio.cleanedAudioSinkFactory
        deps.echoCancellationEnabled = config.audioCapture.echoCancellationEnabled
        deps.cleanedMicPathWriter = writer
        return MenuBarViewModel(dependencies: deps)
    }
}

