import Domain
import DuckDB
import Foundation
import Logging
import Utilities

public actor DuckDBReaderActor: DiarizationReadRepository, NotesReadRepository, RecordingReadRepository, SummaryReadRepository, TranscriptReadRepository {
    private let storageQueue = DispatchSerialQueue(label: "app.the-record.duckdb", qos: .utility)
    public nonisolated var unownedExecutor: UnownedSerialExecutor {
        storageQueue.asUnownedSerialExecutor()
    }

    public let database: Database
    // internal (not private): DuckDBReaderActorAdmin.swift accesses these via a cross-file
    // extension in the same module. Swift private is file-scoped; actor isolation is the
    // actual safety boundary here.
    let connection: Connection
    let logger = AppLogger.for(category: "DuckDBStorage")

    public init(databasePath: URL?) throws {
        do {
            let store: Database.Store = if let path = databasePath {
                .file(at: path)
            } else {
                .inMemory
            }
            database = try DuckDBInit.openDatabase(store: store)
            connection = try database.connect()
            try Self.setupSchema(connection: connection)
        } catch {
            print("DUCKDB INIT ERROR: \(error)")
            throw StorageError.readFailed(underlying: error)
        }
    }

    private static func setupSchema(connection: Connection) throws {
        // Required DDL statements — any failure is fatal.
        try executeRequired(connection: connection, sql: DuckDBSQL.createRecordings, label: "createRecordings")
        try executeRequired(connection: connection, sql: DuckDBSQL.createSegments, label: "createSegments")
        try executeRequired(connection: connection, sql: DuckDBSQL.createCommitmentsTable, label: "createCommitmentsTable")
        try executeRequired(connection: connection, sql: DuckDBSQL.createMeetingNotes, label: "createMeetingNotes")
        try executeRequired(connection: connection, sql: DuckDBSQL.createSummaries, label: "createSummaries")
        try executeRequired(connection: connection, sql: DuckDBSQL.createRecordingsIndex, label: "createRecordingsIndex")

        // Additive migrations — tolerate "already exists" / "duplicate" / "reason: nil" errors.
        // Migration for existing databases: add is_pending if not present.
        try executeMigration(connection: connection, sql: DuckDBSQL.addIsPendingColumn, label: "addIsPendingColumn")
        // Migration for Epic 21: add word_timings VARCHAR column to diarized_segments if not present.
        try executeMigration(connection: connection, sql: DuckDBSQL.addWordTimingsColumn, label: "addWordTimingsColumn")
        // Migration for epic-28 / task-003: add cleaned_mic_audio_url column if not present.
        try executeMigration(connection: connection, sql: DuckDBSQL.addCleanedMicAudioUrlColumn, label: "addCleanedMicAudioUrlColumn")

        try executeRequired(connection: connection, sql: DuckDBSQL.createInferenceTelemetry, label: "createInferenceTelemetry")

        // Bump schema version to reflect the legacy DDL baseline so the migration runner
        // skips steps v0→v4 (already applied above) and only runs pending steps above v4.
        try connection.execute(DuckDBSQL.createSchemaVersion)
        let versionResult = try connection.query(DuckDBSQL.readSchemaVersion)
        let currentVersion: Int32 = versionResult.rowCount > 0
            ? (versionResult[0].cast(to: Int32.self)[0] ?? 0)
            : 0
        if currentVersion < 4 {
            try connection.execute(DuckDBSQL.setSchemaVersion(4))
        }
        do {
            try DuckDBMigrationRunner().migrate(connection: connection)
        } catch {
            // Revert the baseline bump so the next startup can retry rather than boot-loop.
            if currentVersion < 4 {
                try? connection.execute(DuckDBSQL.setSchemaVersion(currentVersion))
            }
            throw error
        }
    }

    /// Executes a DDL statement that must succeed — any error is fatal.
    private static func executeRequired(connection: Connection, sql: String, label: String) throws {
        do {
            try connection.execute(sql)
        } catch {
            print("FAILED \(label): \(error)")
            throw error
        }
    }

    /// Executes an additive migration statement. Errors that indicate the column/table already
    /// exists ("exists", "duplicate", "reason: nil") are silently swallowed; others are rethrown.
    private static func executeMigration(connection: Connection, sql: String, label: String) throws {
        do {
            try connection.execute(sql)
        } catch {
            print("FAILED \(label): \(error)")
            let desc = String(describing: error).lowercased()
            if !desc.contains("exists"), !desc.contains("duplicate"), !desc.contains("reason: nil") {
                throw error
            }
        }
    }

    public init() throws {
        let dbDir = Directories.appSupport
        try Directories.ensureDirectory(at: dbDir)
        let dbURL = dbDir.appendingPathComponent(AppConstants.Paths.databaseFileName)
        try self.init(databasePath: dbURL)
    }

    // MARK: - Prepared Statement Helper

    func prepared(_ sql: String) throws -> PreparedStatement {
        try PreparedStatement(connection: connection, query: sql)
    }
}

