static func openDatabase(store: Database.Store) throws -> Database {
    var lastError: Error?
    for attempt in 0..<3 {
        lock.lock()
        let openResult: Result<Database, Error> = Result { try Database(store: store) }
        lock.unlock()
        switch openResult {
        case .success(let database):
