            }
            return database
        case .failure(let error):
            lastError = error
            // Lock errors mean a prior instance is still shutting down. Retry twice with
            // a short pause — the OS releases flock() when the process fully exits.
            let isLockError = String(describing: error).lowercased().contains("lock")
            guard isLockError, attempt < 2 else { break }
            Thread.sleep(forTimeInterval: 0.5)
        }
    }
    throw lastError!
}

