import Foundation
import Domain

// MARK: - CleanupState

/// Models the async cleanup transcription pass.
///
/// Transitions forward only: `.idle` → `.running` → `.complete`.
/// Enforces **ISOL-001**: structurally independent from `PipelineState`.
public enum CleanupState: Sendable {
    case idle
    case running
    case complete(TranscriptionResult)

    public var isRunning: Bool {
        if case .running = self { return true }
        return false
    }
}

// MARK: - PipelineState

/// Models the diarization → summarization pipeline.
///
/// A single enum value guarantees **SAFE-001**: `.diarizing` and `.summarizing`
/// can never be simultaneously true — only one case is active at a time.
/// Transitions forward only: `.idle` → `.diarizing` → `.summarizing` → `.complete`.
public enum PipelineState: Sendable {
    case idle
    case diarizing
    case summarizing(DiarizedTranscript)
    case complete(DiarizedTranscript, MeetingSummary)
    case failed(String)

    /// True only when the pipeline is actively running diarization.
    /// **SAFE-001**: structurally impossible to be true while `isSummarizing` is true.
    public var isDiarizing: Bool {
        if case .diarizing = self { return true }
        return false
    }

    /// True only when the pipeline is actively running summarization.
    /// **SAFE-001**: structurally impossible to be true while `isDiarizing` is true.
    public var isSummarizing: Bool {
        if case .summarizing = self { return true }
        return false
    }

    /// Non-nil IFF the state is `.summarizing` or `.complete` (**INV-002**).
    public var diarizedTranscript: DiarizedTranscript? {
        switch self {
        case let .summarizing(dt): dt
        case let .complete(dt, _): dt
        default: nil
        }
    }

    /// Non-nil IFF the state is `.complete` (**INV-003**).
    public var summary: MeetingSummary? {
        if case let .complete(_, ms) = self { return ms }
        return nil
    }
}

