import Business
import Domain
import Foundation
import Logging
import Observation

@Observable @MainActor
public final class BroadsheetAppState: CustomReflectable {
    let logger = AppLogger.for(category: "BroadsheetAppState")

    public var selectedMeetingID: RecordingID?
    public var selectedTab: BroadsheetTab = .notes
    public var selectedSidebarItem: BroadsheetSidebarItem = .inbox
    public var searchQuery = ""
    public var askQuery = ""
    public var toast: ToastMessage?
    var toastDismissTask: Task<Void, Never>?

    public let menuBarVM: MenuBarViewModel
    public let libraryVM: MeetingLibraryViewModel
    public let detailVM: MeetingDetailViewModel
    public let commitmentsVM: CommitmentsViewModel
    public let exportTranscriptUseCase: ExportTranscriptUseCase

    var summaryRecordingIDs: Set<RecordingID> = []

    public var isRecording: Bool {
        menuBarVM.isRecording
    }

    public var selectedMeeting: RecordingMetadata? {
        detailVM.selectedMeeting
    }

    public struct MeetingDateGroup: Identifiable {
        public let date: String
        public let label: String
        public let meetings: [MeetingDisplayModel]
        public var id: String {
            date
        }
    }

    /// @MainActor required here: static members are NOT automatically isolated to the
    /// type-level actor. Without this annotation, accessing groupFormatter from @MainActor
    /// context would require an await hop to the static member's executor.
    // swiftlint:disable no_nsformatter_instantiation
    // safe: @MainActor isolation serialises all access to this non-Sendable formatter
    @MainActor private static let groupFormatter: DateFormatter = {
        let f = DateFormatter()
        f.dateStyle = .medium
        f.timeStyle = .none
        return f
    }()

    // swiftlint:enable no_nsformatter_instantiation

    /// Stored — updated only on recording start/stop so views observing
    /// `displayedMeetings` don't re-evaluate on every `currentSession` mutation
    /// (e.g. duration ticks). Fixes over-observation (#167).
    public internal(set) var liveRecordingID: RecordingID? {
        didSet { recomputeGroupedMeetings() }
    }

    /// Computed — `@Observable` auto-tracks `libraryVM.meetings` and the stored
    /// `liveRecordingID`. Views update when meetings load or recording starts/stops,
    /// not on every `currentSession` property mutation.
    public var displayedMeetings: [MeetingDisplayModel] {
        libraryVM.meetings.map {
            MeetingDisplayModel.from($0, isLive: $0.id == liveRecordingID, hasSummary: summaryRecordingIDs.contains($0.id))
        }
    }

    /// Stored — recomputed only when `liveRecordingID` changes or meetings reload.
    /// Avoids O(n log n) Dictionary+sort on every SwiftUI body evaluation (#168).
    public private(set) var groupedDisplayedMeetings: [MeetingDateGroup] = []

    /// Stored property updated incrementally by `appendSegment(_:)` — O(1) per append
    /// instead of O(n) on every access. Cleared by `clearLiveTranscript()`.
    public var liveTranscriptTurns: [TranscriptTurnDisplay] = []

    /// Forwards the segment to `liveTranscriptionVM` for segment-level storage.
    /// `liveTranscriptionVM` fires `onSegmentAppended` → `handleLiveSegment`, which
    /// performs the single authoritative write to `liveTranscriptTurns`.
    public func appendSegment(_ segment: StreamingSegment) {
        menuBarVM.liveTranscriptionVM?.appendSegment(segment)
    }

    /// Clears all live transcript turns. Call when a recording session ends or resets.
    public func clearLiveTranscript() {
        liveTranscriptTurns.removeAll()
    }

    public var selectedDisplayMeeting: MeetingDisplayModel? {
        guard let id = selectedMeetingID,
              let meta = libraryVM.meetings.first(where: { $0.id == id }) else { return nil }
        return MeetingDisplayModel.from(meta, isLive: meta.id == liveRecordingID, hasSummary: summaryRecordingIDs.contains(meta.id))
    }

    public init(
        menuBarVM: MenuBarViewModel,
        libraryVM: MeetingLibraryViewModel,
        detailVM: MeetingDetailViewModel,
        commitmentsVM: CommitmentsViewModel,
        exportTranscriptUseCase: ExportTranscriptUseCase = ExportTranscriptUseCase()
    ) {
        self.menuBarVM = menuBarVM
        self.libraryVM = libraryVM
        self.detailVM = detailVM
        self.commitmentsVM = commitmentsVM
        self.exportTranscriptUseCase = exportTranscriptUseCase
        menuBarVM.liveTranscriptionVM?.onSegmentsAppended = { [weak self] segments in
            for segment in segments {
                self?.handleLiveSegment(segment)
            }
        }
        recomputeGroupedMeetings()
    }

    // MARK: - Private Helpers

    func recomputeGroupedMeetings() {
        let grouped = Dictionary(grouping: displayedMeetings) { Self.groupFormatter.string(from: $0.date) }
        groupedDisplayedMeetings = grouped
            .map { MeetingDateGroup(date: $0.key, label: $0.key.uppercased(), meetings: $0.value) }
            .sorted { ($0.meetings.first?.date ?? .now) > ($1.meetings.first?.date ?? .now) }
    }

    private func handleLiveSegment(_ segment: StreamingSegment) {
        if !liveTranscriptTurns.isEmpty {
            var last = liveTranscriptTurns[liveTranscriptTurns.count - 1]
            if last.isCurrent {
                last = TranscriptTurnDisplay(
                    id: last.id, timestamp: last.timestamp,
                    speakerName: last.speakerName, channelLabel: last.channelLabel,
                    text: last.text, isCurrent: false
                )
                liveTranscriptTurns[liveTranscriptTurns.count - 1] = last
            }
        }
        liveTranscriptTurns.append(TranscriptTurnDisplay.from(segment, meetingId: selectedMeetingID, isCurrent: true))
    }

    var loadTask: Task<Void, Never>?

    public func reloadDisplayedMeetings() {
        recomputeGroupedMeetings()
    }

    // CustomReflectable: label-only stub — real value access is intentionally omitted.
    // `@MainActor` isolation prevents a `nonisolated` getter from reading `liveTranscriptTurns`
    // directly; the test verifies only that the label "liveTranscriptTurns" is present.
    public nonisolated var customMirror: Mirror {
        Mirror("BroadsheetAppState", children: [("liveTranscriptTurns", Void?.none as Any)], displayStyle: .class)
    }

    // MARK: - Toast

    public func showToast(_ message: ToastMessage) {
        toastDismissTask?.cancel()
        toast = message
        if let duration = message.duration {
            toastDismissTask?.cancel()
            toastDismissTask = Task { [weak self] in
                do { try await Task.sleep(for: .seconds(duration)) } catch { return }
                self?.toast = nil
            }
        }
    }

    public func dismissToast() {
        toastDismissTask?.cancel()
        toast = nil
    }
}

