@Observable
@MainActor
public final class MenuBarViewModel {
    public var lastTranscription: TranscriptionResult?
    public var errorMessage: String?
    public var settingsDeepLink: URL?
    public var cleanupRecordingId: RecordingID?
    static let readyStatus = "Ready"
    public var statusMessage = MenuBarViewModel.readyStatus
    public var downloadProgress: ModelDownloadProgress?
    public var searchQuery = ""

    // MARK: - State Enums (task-002)

    /// Tracks the async cleanup transcription pass lifecycle.
    public var cleanupState: CleanupState = .idle

    /// Tracks the diarization → summarization pipeline lifecycle.
    public var pipelineState: PipelineState = .idle

    public var recordings: [RecordingSummary] = []
    public var upcomingMeetings: [CalendarMeeting] = []
    public var upcomingMeetingsAsOf = Date()
    public var isLoadingUpcomingMeetings = false
    public var folderWarning: FolderSizeWarning?

    // MARK: - Forwarding computed properties (#170)

    // Delegate to recordingStateVM — do NOT read any stored @Observable property of
    // MenuBarViewModel here. Under Swift Observation a view reading e.g. `isRecording`
    // tracks recordingStateVM.isRecording precisely. Adding a MenuBarViewModel stored-
    // property read would widen the observation surface and cause over-rendering.

    public var isRecording: Bool {
        recordingStateVM.isRecording
    }

    public var currentSession: RecordingSession? {
        recordingStateVM.currentSession
    }

    public var recordingState: RecordingUIState {
        get { recordingStateVM.recordingState }
        set { recordingStateVM.recordingState = newValue }
    }

    public var recordingStartTime: Date? {
        recordingStateVM.recordingStartTime
    }

    public var canStopRecording: Bool {
        recordingStateVM.canStopRecording
    }

    public var autoRecordEnabled: Bool {
        recordingStateVM.autoRecordEnabled
    }

    public var displayedTranscription: TranscriptionResult? {
        if case let .complete(r) = cleanupState { return r }
        return lastTranscription
    }

    public let recordingStateVM: RecordingStateViewModel

    public let pipelineCoordinator: PipelineCoordinator
    let deleteRecordingUseCase: DeleteRecordingUseCase
    let searchRecordingsUseCase: SearchRecordingsUseCase
    let autoCleanupUseCase: AutoCleanupUseCase
    let exportAudioUseCase: ExportAudioUseCase
    let listUpcomingMeetingsUseCase: ListUpcomingMeetingsUseCase?
    let migrationTask: Task<Void, Never>?
    public let engine: TheRecordEngine?
    public let contextSuggestionsVM: ContextSuggestionsViewModel?
    public let liveTranscriptionVM: LiveTranscriptionViewModel?
    public let waveformVM: WaveformViewModel?
    var searchDebounceTask: Task<Void, Never>?
    public var engineFanOutTask: Task<Void, Never>?
    public let logger = AppLogger.for(category: "MenuBar")

    public init(dependencies: Dependencies) {
        recordingStateVM = RecordingStateViewModel(
            startRecording: dependencies.startRecording,
            stopAndTranscribe: dependencies.stopAndTranscribe,
            liveTranscriptionVM: dependencies.liveTranscriptionVM,
            waveformVM: dependencies.waveformVM,
            streamingTranscription: dependencies.streamingTranscription,
            liveTranslation: dependencies.liveTranslation,
            streamingModelId: dependencies.streamingModelId,
            micAECProcessor: dependencies.micAECProcessor,
            sleepAssertionService: dependencies.sleepAssertionService,
            cleanedAudioSinkFactory: dependencies.cleanedAudioSinkFactory,
            echoCancellationEnabled: dependencies.echoCancellationEnabled,
            cleanedMicPathWriter: dependencies.cleanedMicPathWriter
        )
        pipelineCoordinator = dependencies.pipelineCoordinator
        deleteRecordingUseCase = dependencies.deleteRecording
        searchRecordingsUseCase = dependencies.searchRecordings
        autoCleanupUseCase = dependencies.autoCleanup
        exportAudioUseCase = dependencies.exportAudio
        listUpcomingMeetingsUseCase = dependencies.listUpcomingMeetings
        migrationTask = dependencies.migrationTask
        engine = dependencies.engine
        contextSuggestionsVM = dependencies.contextSuggestionsVM
        liveTranscriptionVM = dependencies.liveTranscriptionVM
        waveformVM = dependencies.waveformVM

        let coordinator = dependencies.pipelineCoordinator
        Task { [weak self] in
            await coordinator.setOnCleanupStateChanged { @Sendable [weak self] state in
                Task { @MainActor in self?.cleanupState = state }
            }
            await coordinator.setOnPipelineStateChanged { @Sendable [weak self] state in
                Task { @MainActor in self?.pipelineState = state }
            }
            await coordinator.setOnPipelineError { @Sendable [weak self] errorMsg in
                Task { @MainActor in self?.errorMessage = errorMsg }
            }
        }
    }

    public func startRecordingTapped() async {
        await pipelineCoordinator.cancelAll()
        errorMessage = nil
        contextSuggestionsVM?.updateSuggestions([])
        statusMessage = "Starting..."
        let result = await recordingStateVM.startRecording()
        switch result {
        case .success:
            statusMessage = "Recording"
            NotificationCenter.default.post(name: .recordingStarted, object: nil)
        case let .failure(error):
            errorMessage = mapError(error)
            statusMessage = Self.readyStatus
        }
    }

    public func runSummarizationPass(recordingId: RecordingID, transcript: DiarizedTranscript) async {
        await pipelineCoordinator.runSummarizationPass(recordingId: recordingId, transcript: transcript)
    }

    public func runCleanupPass(recordingId: RecordingID) async -> TranscriptionResult? {
        return await pipelineCoordinator.runCleanupPass(recordingId: recordingId)
    }

    public func recoverPendingSession(_ recordingId: RecordingID) async {
        await pipelineCoordinator.recoverPendingSession(recordingId)
    }

    func handleRecordingCompleted(_ transcribed: TranscribedRecording) {
        lastTranscription = transcribed.transcription
        cleanupState = .idle
        pipelineState = .idle
        statusMessage = Self.readyStatus
        let recordingId = transcribed.recording.metadata.id
        cleanupRecordingId = recordingId

        Task { [weak self] in
            guard let self else { return }
            await pipelineCoordinator.startCleanupPass(for: recordingId)
            await pipelineCoordinator.startPipeline(for: recordingId, liveTranscription: transcribed.transcription)
        }

        feedToEngine(segments: transcribed.transcription.segments, meetingId: recordingId)
        // Signal alignment to start in the background (Pro-tier only; nil on free tier).
        // recordingCompleted is nonisolated — no await needed.
        engine?.recordingCompleted(recordingId: recordingId)
    }

    public func stopRecordingTapped() async {
        guard recordingStateVM.currentSession != nil else {
            logger.warning("Stop tapped with no active session — ignoring")
            return
        }
        statusMessage = "Transcribing..."
        let result = await recordingStateVM.stopRecording()
        switch result {
        case let .success(transcribed):
            handleRecordingCompleted(transcribed)
        case let .failure(error):
            errorMessage = mapError(error)
            statusMessage = Self.readyStatus
        }
        NotificationCenter.default.post(name: .recordingStopped, object: nil)
    }
}

import Business
import Domain
import Logging
import SwiftUI

@Observable
@MainActor
public final class RecordingStateViewModel {
    public var isRecording: Bool { currentSession != nil }
    public var currentSession: RecordingSession?
    public var recordingState: RecordingUIState = .idle
    public internal(set) var recordingStartTime: Date?
    public var canStopRecording: Bool { recordingState == .recording }

    // MARK: - Storage guard (#124)

    /// Disk space below this threshold blocks recording from starting.
    public static let insufficientDiskSpaceThresholdBytes: Int64 = 100 * 1_048_576  // 100 MB

    /// Disk space below this threshold (but above the block threshold) shows a warning.
    public static let lowDiskSpaceWarningThresholdBytes: Int64 = 500 * 1_048_576  // 500 MB

    /// Set to `true` when available disk space is below the warning threshold but above
    /// the hard block threshold. Clears when recording stops.
    public var lowDiskSpaceWarning: Bool = false

    // MARK: - Max duration cap (#124)

    /// Maximum recording duration before auto-stop (4 hours in seconds).
    public static let maxRecordingDurationSeconds: Int = 14_400

    /// Duration at which a "nearly at limit" warning fires (3 hours 50 minutes).
    public static let durationWarningSeconds: Int = 13_800

    /// Set to `true` when the recording has been running for `durationWarningSeconds`
    /// or more. Clears when recording stops.
    public var durationWarningActive: Bool = false

    let startRecording: StartRecordingUseCase
    let stopAndTranscribe: StopAndTranscribeUseCase
    let liveTranscriptionVM: LiveTranscriptionViewModel?
    let waveformVM: WaveformViewModel?
    let streamingTranscription: StreamingTranscriptionUseCase?
    let liveTranslation: LiveTranslateUseCase?
    let streamingModelId: ModelID
    let micAECProcessor: (any MicAECProcessor)?
    nonisolated(unsafe) let sleepAssertionService: (any SleepAssertionService)?
    /// Factory for a per-session cleaned-audio WAV sink (epic-28 / task-003).
    let cleanedAudioSinkFactory: (@Sendable (Date) -> any CleanedAudioSink)?
    /// Captured once at `startMicStream`; mid-session toggle changes have no effect (ORD-002).
    let echoCancellationEnabled: Bool
    /// Persists the cleaned-mic file reference after finalize (epic-28 / task-003).
    let cleanedMicPathWriter: (any RecordingWriteRepository)?
    /// Optional disk space monitor for pre-recording guard (#124).
    nonisolated(unsafe) let diskSpaceMonitor: (any DiskSpaceMonitor)?
    /// Per-session recording notice consent gate (issue #68 / REQ-A1).
    let recordingNoticeViewModel: RecordingNoticeViewModel?

    static let sleepPreventionReason = "THE RECORD: Active recording session"
    let logger = AppLogger.for(category: "Recording")

    var liveStreamTask: Task<Void, Never>?
    var micStreamTask: Task<Void, Never>?
    private var autoRecordTask: Task<Void, Never>?
    var startTask: Task<Result<RecordingSession, Error>, Never>?
    @ObservationIgnored var systemAudioRingBuffer: [TaggedAudioBuffer] = []
    var throttleTask: Task<Void, Never>?
    public var autoRecordEnabled = false
    /// Active sink for the current recording session (nil when AEC is OFF).
    var activeSink: (any CleanedAudioSink)?

    public nonisolated init(
        startRecording: StartRecordingUseCase,
        stopAndTranscribe: StopAndTranscribeUseCase,
        liveTranscriptionVM: LiveTranscriptionViewModel? = nil,
        waveformVM: WaveformViewModel? = nil,
        streamingTranscription: StreamingTranscriptionUseCase? = nil,
        liveTranslation: LiveTranslateUseCase? = nil,
        streamingModelId: ModelID = ModelIDs.streamingFallback,
        micAECProcessor: (any MicAECProcessor)? = nil,
        sleepAssertionService: (any SleepAssertionService)? = nil,
        cleanedAudioSinkFactory: (@Sendable (Date) -> any CleanedAudioSink)? = nil,
        echoCancellationEnabled: Bool = true,
        cleanedMicPathWriter: (any RecordingWriteRepository)? = nil,
        diskSpaceMonitor: (any DiskSpaceMonitor)? = nil,
        recordingNoticeViewModel: RecordingNoticeViewModel? = nil
    ) {
        self.startRecording = startRecording
        self.stopAndTranscribe = stopAndTranscribe
        self.liveTranscriptionVM = liveTranscriptionVM
        self.waveformVM = waveformVM
        self.streamingTranscription = streamingTranscription
        self.liveTranslation = liveTranslation
        self.streamingModelId = streamingModelId
        self.micAECProcessor = micAECProcessor
        self.sleepAssertionService = sleepAssertionService
        self.cleanedAudioSinkFactory = cleanedAudioSinkFactory
        self.echoCancellationEnabled = echoCancellationEnabled
        self.cleanedMicPathWriter = cleanedMicPathWriter
        self.diskSpaceMonitor = diskSpaceMonitor
        self.recordingNoticeViewModel = recordingNoticeViewModel
    }

    public func startRecording() async -> Result<RecordingSession, Error> {
        if let existing = startTask { return await existing.value }
        let task = Task { @MainActor [weak self] () -> Result<RecordingSession, Error> in
            guard let self else { return .failure(RecordingError.notRecording) }

            // MARK: Recording notice consent gate (issue #68 / REQ-A1)
            if let noticeVM = self.recordingNoticeViewModel, !noticeVM.recordingIsAllowed {
                return .failure(RecordingError.noticeRequired)
            }

            // MARK: Disk space pre-check (#124)
            if let monitor = self.diskSpaceMonitor {
                let available = await monitor.availableBytes()
                if available < Self.insufficientDiskSpaceThresholdBytes {
                    // Hard block — not enough space to record.
                    return .failure(RecordingError.insufficientDiskSpace)
                } else if available < Self.lowDiskSpaceWarningThresholdBytes {
                    self.lowDiskSpaceWarning = true
                } else {
                    self.lowDiskSpaceWarning = false
                }
            }

            do {
                let session = try await self.startRecording.start()
                self.currentSession = session
                self.recordingState = .recording
                self.recordingStartTime = Date()
                _ = self.sleepAssertionService?.preventSleep(reason: Self.sleepPreventionReason)
                self.logger.info("Recording started — session: \(session.id, privacy: .private)")
                self.liveTranscriptionVM?.meetingId = session.id
                self.liveTranscriptionVM?.clear()
                if let bufferStream = await self.startRecording.getSystemStream() {
                    self.startLiveStream(bufferStream: bufferStream, meetingId: session.id)
                }
                if let micStream = await self.startRecording.getMicStream() {
                    self.startMicStream(micStream: micStream, meetingId: session.id)
                }
                return .success(session)
            } catch {
                self.recordingState = .idle
                self.currentSession = nil
                self.logError(error, context: "Start recording failed")
                return .failure(error)
            }
        }
        startTask = task
        let result = await task.value
        startTask = nil
        return result
    }

    public func startAutoRecording(
        detector: any MeetingDetector,
        onMeetingStarted: @escaping () async -> Void,
        onMeetingStopped: @escaping () async -> Void,
        isRecording: @escaping () -> Bool
    ) {
        autoRecordTask?.cancel()
        autoRecordEnabled = true
        autoRecordTask = Task { [weak self] in
            for await event in detector.events() {
                guard let self, !Task.isCancelled else { break }
                switch event {
                case .meetingStarted:
                    if !isRecording() {
                        logger.info("Auto-record: meeting detected, starting recording")
                        await onMeetingStarted()
                    }
                case .meetingStopped:
                    if isRecording() {
                        logger.info("Auto-record: meeting ended, stopping recording")
                        await onMeetingStopped()
                    }
                }
            }
        }
    }

    public func stopAutoRecording() {
        autoRecordTask?.cancel()
        autoRecordTask = nil
        autoRecordEnabled = false
    }
}

