import Domain
import SwiftUI

/// Main window — NavigationSplitView with sidebar and detail panel.
/// TASK-022: full assembly replacing the TASK-009 skeleton.
@MainActor
public struct MainWindowView: View {
    @Bindable public var menuBarVM: MenuBarViewModel
    @Bindable public var libraryVM: MeetingLibraryViewModel
    @Bindable public var searchVM: SearchViewModel
    @Bindable public var detailVM: MeetingDetailViewModel
    @Bindable public var waveformVM: WaveformViewModel
    @Bindable public var commitmentsVM: CommitmentsViewModel
    public var audioPlayerVM: AudioPlayerViewModel

    @State private var selection: RecordingID?
    @State private var detailTab: DetailTab = .transcript

    public init(
        menuBarVM: MenuBarViewModel,
        libraryVM: MeetingLibraryViewModel,
        searchVM: SearchViewModel,
        detailVM: MeetingDetailViewModel,
        waveformVM: WaveformViewModel,
        commitmentsVM: CommitmentsViewModel,
        audioPlayerVM: AudioPlayerViewModel
    ) {
        self.menuBarVM = menuBarVM
        self.libraryVM = libraryVM
        self.searchVM = searchVM
        self.detailVM = detailVM
        self.waveformVM = waveformVM
        self.commitmentsVM = commitmentsVM
        self.audioPlayerVM = audioPlayerVM
    }

    public var body: some View {
        NavigationSplitView(columnVisibility: .constant(.all)) {
            MeetingLibrarySidebarView(
                libraryVM: libraryVM,
                searchVM: searchVM,
                selection: $selection
            )
        } detail: {
            VStack(spacing: 0) {
                WaveformView(viewModel: waveformVM)
                ErrorBannerView(errorMessage: $libraryVM.errorMessage)
                if menuBarVM.recordingState == .recording {
                    RecordingLiveView(menuBarVM: menuBarVM)
                } else if libraryVM.meetings.isEmpty {
                    EmptyStateView {
                        Task { await menuBarVM.startRecordingTapped() }
                    }
                } else if detailVM.selectedMeeting == nil {
                    Text(String(localized: "Select a meeting"))
                        .foregroundStyle(.secondary)
                        .frame(maxWidth: .infinity, maxHeight: .infinity)
                } else {
                    CleanupProgressView(isVisible: menuBarVM.cleanupState.isRunning)
                    TabSwitcherView(selection: $detailTab)
                    switch detailTab {
                    case .transcript:
                        TranscriptTabView(viewModel: detailVM, audioPlayerViewModel: audioPlayerVM)
                    case .summary:
                        SummaryTabView(viewModel: detailVM)
                    case .commitments:
                        CommitmentsTabView(
                            viewModel: commitmentsVM,
                            currentMeetingId: detailVM.selectedMeeting?.id
                        )
                    case .context:
                        if let suggestionsVM = menuBarVM.contextSuggestionsVM {
                            ContextSuggestionsPanelView(viewModel: suggestionsVM)
                        } else {
                            Text(String(localized: "Context suggestions unavailable"))
                                .foregroundStyle(.secondary)
                                .accessibilityLabel(String(localized: "Context suggestions unavailable"))
                        }
                    }
                }
            }
        }
        .frame(minWidth: 800, minHeight: 600)
        .toolbar {
            ToolbarItem(placement: .primaryAction) {
                recordToolbarButton
            }
        }
        .task { await libraryVM.loadMeetingsAndCaptureError() }
        // BM-035: .task(id:) cancels the prior detail load when selection changes.
        .task(id: selection) {
            guard let id = selection,
                  let meeting = libraryVM.meetings.first(where: { $0.id == id })
            else { return }
            do {
                try await detailVM.loadDetail(for: meeting)
            } catch {
                libraryVM.errorMessage = "Failed to load meeting: \(error.userFacingMessage)"
            }
        }
    }

    private var recordToolbarButton: some View {
        Button {
            Task {
                if menuBarVM.recordingState == .recording {
                    await menuBarVM.stopRecordingTapped()
                } else {
                    await menuBarVM.startRecordingTapped()
                }
            }
        } label: {
            Label(
                menuBarVM.recordingState == .recording ? "Stop" : "Record",
                systemImage: menuBarVM.recordingState == .recording
                    ? "stop.circle.fill"
                    : "record.circle"
            )
        }
        .keyboardShortcut("r", modifiers: [.command])
        .disabled(menuBarVM.recordingState == .processing)
        .accessibilityLabel(
            menuBarVM.recordingState == .recording
                ? String(localized: "Stop recording")
                : String(localized: "Start recording")
        )
    }
}

import Domain
import Foundation
import Observation

/// Manages microphone, screen-capture, and calendar permission state for `OnboardingView`.
///
/// Accepts any `PermissionService` so tests can inject a stub without
/// importing AVFoundation or CoreGraphics.
@Observable
@MainActor
public final class OnboardingViewModel {
    // MARK: - Published State

    public var micStatus: PermissionStatus = .notDetermined
    public var screenGranted = false
    public var calendarStatus: PermissionStatus = .notDetermined

    // MARK: - Computed

    /// Returns true when all three permissions are granted.
    public var allPermissionsGranted: Bool {
        micStatus == .granted && screenGranted && calendarStatus == .granted
    }

    // MARK: - Private

    private let service: any PermissionService
    private static let hasCompletedOnboardingKey = "hasCompletedOnboarding"

    // MARK: - Init

    public init(service: any PermissionService) {
        self.service = service
    }

    // MARK: - Actions

    /// Loads the current permission statuses. Call on `.task {}` or `.onAppear`.
    public func refresh() async {
        async let mic = service.microphoneStatus
        async let screen = service.screenCaptureStatus
        async let calendar = service.calendarStatus
        micStatus = await mic
        screenGranted = await screen == .granted
        calendarStatus = await calendar
    }

    /// Requests microphone access and refreshes `micStatus`.
    public func requestMicrophone() async {
        micStatus = await service.requestMicrophone()
    }

    /// Requests screen-capture access and refreshes `screenGranted`.
    public func requestScreenCapture() async {
        screenGranted = await service.requestScreenCapture() == .granted
    }

    /// Requests calendar access and refreshes `calendarStatus`.
    public func requestCalendar() async {
        calendarStatus = await service.requestCalendar()
    }

    /// Marks onboarding as complete by setting `hasCompletedOnboarding` in UserDefaults.
    public func completeOnboarding() {
        UserDefaults.standard.set(true, forKey: Self.hasCompletedOnboardingKey)
    }
}

import SwiftUI
import AppKit
import Domain
import Logging
import Business
import AudioInfrastructure
import MLInfrastructure
import Presentation

/// The top-level SwiftUI application entry point for THE RECORD.
@main
public struct TheRecordApp: App {
    /// The application delegate managing the status bar, popover, and composition root.
    @NSApplicationDelegateAdaptor(AppDelegate.self) public var appDelegate

    public init() {}

    public var body: some Scene {
        Window("THE RECORD", id: "main") {
            AppContentView(appDelegate: appDelegate)
        }
        .commands {
            CommandGroup(after: .appInfo) {
                Button("Third-Party Licenses") {
                    if let url = Bundle.main.url(forResource: "ThirdPartyLicenses", withExtension: "txt") {
                        NSWorkspace.shared.open(url)
                    }
                }
            }
            CommandGroup(after: .newItem) {
                Button("New Meeting") {
                    Task { @MainActor in
                        await appDelegate.menuBarVM?.startRecordingTapped()
                    }
                }
                .keyboardShortcut("n", modifiers: .command)
                .disabled(appDelegate.menuBarVM?.isRecording == true)
                Divider()
                Button("Stop Recording") {
                    Task { @MainActor in
                        await appDelegate.menuBarVM?.stopRecordingTapped()
                    }
                }
                .keyboardShortcut(".", modifiers: .command)
                Divider()
                Button("Re-transcribe from Audio") {
                    Task { @MainActor in
                        if let id = appDelegate.menuBarVM?.cleanupRecordingId {
                            _ = await appDelegate.menuBarVM?.runCleanupPass(recordingId: id)
                        }
                    }
                }
                .keyboardShortcut("r", modifiers: [.command, .shift])
                .disabled(appDelegate.menuBarVM?.cleanupRecordingId == nil || appDelegate.menuBarVM?
                    .isRecording == true)
            }
        }
        Settings {
            SettingsView(
                viewModel: SettingsViewModel(
                    audioDeviceConfigStore: AudioDeviceConfigStoreImpl(configManager: appDelegate.sharedConfigManager),
                    deviceEnumeration: AudioDeviceEnumerator(),
                    currentThemeProvider: { appDelegate.uiTheme },
                    currentEngineProvider: { appDelegate.defaultEngine },
                    currentArchivePassEnabledProvider: { appDelegate.archivePassEnabled },
                ),
                // setenv is the only supported injection point for HF_TOKEN into the
                // WhisperKit/Parakeet/MLX download process; token is unset immediately via defer.
                // swiftlint:disable no_setenv
                modelDownloadViewModel: ModelDownloadViewModel(
                    downloadWhisper: { modelId, token in
                        let typedModelId = ModelID(modelId)
                        if let token { setenv("HF_TOKEN", token, 1) } // swiftlint:disable:this no_setenv
                        defer { if token != nil { unsetenv("HF_TOKEN") } }
                        try await WhisperKitPlugin().loadModel(typedModelId)
                    },
                    downloadParakeet: { modelId, token in
                        let typedModelId = ModelID(modelId)
                        if let token { setenv("HF_TOKEN", token, 1) } // swiftlint:disable:this no_setenv
                        defer { if token != nil { unsetenv("HF_TOKEN") } }
                        try await ParakeetPlugin().loadModel(typedModelId)
                    },
                    downloadMLX: { modelId, token in
                        let config = SummaryConfig(
                            modelId: ModelID(modelId),
                            maxTokens: SummaryConfig.default.maxTokens,
                            temperature: SummaryConfig.default.temperature,
                            enabled: true,
                            meetingType: SummaryConfig.default.meetingType,
                        )
                        if let token { setenv("HF_TOKEN", token, 1) } // swiftlint:disable:this no_setenv
                        defer { if token != nil { unsetenv("HF_TOKEN") } }
                        try await MLXSummarizationPlugin().loadModel(config)
                    },
                    downloadDiarization: {
                        try await FluidDiarizationPlugin().prepare()
                    },
                    tokenStore: HFTokenKeychain(),
                ),
                // swiftlint:enable no_setenv
            )
        }
    }
}

// MARK: - Root Content View

struct AppContentView: View {
    var appDelegate: AppDelegate
    // AudioPlayerViewModel is owned here and passed into MainWindowView so
    // Presentation never needs to import AVFoundation or Infrastructure directly.
    @State private var audioPlayerVM = AudioPlayerViewModel(driver: AVPlayerDriver())

    var body: some View {
        if let menuBarVM = appDelegate.menuBarVM,
           let libraryVM = appDelegate.libraryVM,
           let searchVM = appDelegate.searchVM,
           let detailVM = appDelegate.detailVM,
           let waveformVM = menuBarVM.waveformVM,
           let commitmentsVM = appDelegate.commitmentsVM {
            switch appDelegate.uiTheme {
            case .broadsheet:
                if let appState = appDelegate.broadsheetAppState {
                    BroadsheetRootView(
                        appState: appState,
                        permissionService: SystemPermissionService(),
                    )
                }
            case .classic:
                MainWindowView(
                    menuBarVM: menuBarVM,
                    libraryVM: libraryVM,
                    searchVM: searchVM,
                    detailVM: detailVM,
                    waveformVM: waveformVM,
                    commitmentsVM: commitmentsVM,
                    audioPlayerVM: audioPlayerVM,
                )
            }
        } else {
            ProgressView("Starting THE RECORD...")
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        }
    }
}

// MARK: - App Delegate

/// The application delegate managing window lifecycle, status bar, and the composition root assembly.
@Observable
@MainActor
public final class AppDelegate: NSObject, NSApplicationDelegate {

    // MARK: - Public Properties

    /// The menu bar status item showing the waveform icon.
    public var statusItem: NSStatusItem?
    /// The popover displayed when the status item is clicked.
    public var popover: NSPopover?

    // MARK: - Private: Lifetime Objects

    private let assembler = AppAssembler()

    /// Library view model held at the composition root so migration errors can be
    /// surfaced before TASK-022 wires it into MainWindowView.
    public private(set) var uiTheme: UITheme = .default
    public private(set) var defaultEngine: TranscriptionEngineKey = TranscriptionConfig.default.defaultEngine
    public private(set) var archivePassEnabled: Bool = TranscriptionConfig.default.archivePassEnabled
    public private(set) var libraryVM: MeetingLibraryViewModel?
    public private(set) var menuBarVM: MenuBarViewModel?
    /// TODO: wire searchVM.meetings + searchVM.transcripts from libraryVM after loadMeetings()
    /// so full-text search returns results. Currently the sidebar accepts search text but
    /// filteredMeetings returns empty until that hydration step is added.
    public private(set) var searchVM: SearchViewModel?
    public private(set) var detailVM: MeetingDetailViewModel?
    public private(set) var commitmentsVM: CommitmentsViewModel?
    /// Stable BroadsheetAppState created once at assembly time — do NOT construct inline in body.
    public private(set) var broadsheetAppState: BroadsheetAppState?
    /// The context suggestions view model.
    public private(set) var contextSuggestionsVM: ContextSuggestionsViewModel?
    private let logger = AppLogger.for(category: "AppDelegate")
    /// The shared configuration manager for persisting and loading app settings.
    public let sharedConfigManager = ConfigManager()
    private var themeObserver: NSObjectProtocol? // periphery:ignore — retained to keep observer alive
    private var privacyModeObserver: NSObjectProtocol? // periphery:ignore — retained to keep observer alive
    private var engineObserver: NSObjectProtocol? // periphery:ignore — retained to keep observer alive
    private var archivePassEnabledObserver: NSObjectProtocol? // periphery:ignore — retained to keep observer alive
    private var recordingStartObserver: NSObjectProtocol? // periphery:ignore — retained to keep observer alive
    private var recordingStopObserver: NSObjectProtocol? // periphery:ignore — retained to keep observer alive
    private var windowKeyObserver: NSObjectProtocol? // periphery:ignore — retained to keep observer alive
    private var currentPrivacyMode: PrivacyMode = .default

    // MARK: - NSApplicationDelegate

    /// Initializes the assembly, status bar, and config observers on app launch.
    public func applicationDidFinishLaunching(_ notification: Notification) {
        let launchConfig = AppConfig.default
        uiTheme = launchConfig.uiTheme
        defaultEngine = launchConfig.transcription.defaultEngine
        archivePassEnabled = launchConfig.transcription.archivePassEnabled
        currentPrivacyMode = launchConfig.privacyMode

        setupConfigObservers()

        Task { @MainActor in
            let assembled = await assembler.assemble(config: launchConfig)
            self.menuBarVM = assembled.menuBarVM
            self.libraryVM = assembled.libraryVM
            self.searchVM = assembled.searchVM
            self.detailVM = assembled.detailVM
            self.commitmentsVM = assembled.commitmentsVM
            self.contextSuggestionsVM = assembled.contextSuggestionsVM
            self.broadsheetAppState = BroadsheetAppState(
                menuBarVM: assembled.menuBarVM,
                libraryVM: assembled.libraryVM,
                detailVM: assembled.detailVM,
                commitmentsVM: assembled.commitmentsVM,
            )

            self.setupStatusBar(viewModel: assembled.menuBarVM)
        }

        // Apply on first key window — window doesn't exist yet during didFinishLaunching.
        windowKeyObserver = NotificationCenter.default.addObserver(
            forName: NSWindow.didBecomeKeyNotification,
            object: nil,
            queue: .main,
        ) { [weak self] _ in
            MainActor.assumeIsolated {
                guard let self else { return }
                self.applyPrivacyMode(self.currentPrivacyMode, isRecording: self.menuBarVM?.isRecording ?? false)
            }
        }

        logger.info("THE RECORD launched")
    }

    public func applicationWillTerminate(_ notification: Notification) {
        assembler.teardown()
    }

    // swiftlint:disable:next function_body_length cyclomatic_complexity
    private func setupConfigObservers() {
        themeObserver = NotificationCenter.default.addObserver(
            forName: .themeChanged, object: nil, queue: .main,
        ) { [weak self] note in
            guard let theme = note.userInfo?["uiTheme"] as? UITheme else { return }
            MainActor.assumeIsolated {
                guard let self else { return }
                self.uiTheme = theme
                // Safe fire-and-forget: weak self closure in NotificationCenter observer prevents
                // retain cycle; config write is short-lived with no cancellation semantics.
                Task { [weak self] in
                    guard let self else { return }
                    do {
                        let current = try await self.sharedConfigManager.load()
                        let updated = AppConfig(
                            summarization: current.summarization, transcription: current.transcription,
                            storage: current.storage, translation: current.translation,
                            contextCache: current.contextCache, audioCapture: current.audioCapture,
                            uiTheme: theme, privacyMode: current.privacyMode,
                            mcpConsentGranted: current.mcpConsentGranted,
                            mcpEndpoints: current.mcpEndpoints,
                            notionEnabled: current.notionEnabled,
                            obsidianVaultPath: current.obsidianVaultPath,
                        )
                        try await self.sharedConfigManager.save(updated)
                    } catch {
                        self.logger.error("Failed to persist theme: \(error, privacy: .public)")
                    }
                }
            }
        }
        privacyModeObserver = NotificationCenter.default.addObserver(
            forName: .privacyModeChanged, object: nil, queue: .main,
        ) { [weak self] note in
            guard let raw = note.userInfo?["privacyMode"] as? String,
                  let mode = PrivacyMode(rawValue: raw)
            else { return }
            MainActor.assumeIsolated {
                guard let self else { return }
                self.currentPrivacyMode = mode
                self.applyPrivacyMode(mode, isRecording: self.menuBarVM?.isRecording ?? false)
                // Safe fire-and-forget: same rationale as theme observer above.
                Task { [weak self] in
                    guard let self else { return }
                    do {
                        let current = try await self.sharedConfigManager.load()
                        let updated = AppConfig(
                            summarization: current.summarization, transcription: current.transcription,
                            storage: current.storage, translation: current.translation,
                            contextCache: current.contextCache, audioCapture: current.audioCapture,
                            uiTheme: current.uiTheme, privacyMode: mode,
                            mcpConsentGranted: current.mcpConsentGranted,
                            mcpEndpoints: current.mcpEndpoints,
                            notionEnabled: current.notionEnabled,
                            obsidianVaultPath: current.obsidianVaultPath,
                        )
                        try await self.sharedConfigManager.save(updated)
                    } catch {
                        self.logger
                            .error("Failed to persist privacy mode: \(String(reflecting: error), privacy: .public)")
                    }
                }
            }
        }
        engineObserver = NotificationCenter.default.addObserver(
            forName: .engineChanged, object: nil, queue: .main,
        ) { [weak self] note in
            guard let raw = note.userInfo?["defaultEngine"] as? String,
                  let engine = TranscriptionEngineKey(rawValue: raw)
            else { return }
            MainActor.assumeIsolated {
                guard let self else { return }
                self.defaultEngine = engine
                Task { [weak self] in
                    guard let self else { return }
                    do {
                        let current = try await self.sharedConfigManager.load()
                        let newTranscription = TranscriptionConfig(
                            defaultEngine: engine,
                            fallbackEngine: current.transcription.fallbackEngine,
                            cleanupModelId: current.transcription.cleanupModelId,
                            archivePassEnabled: current.transcription.archivePassEnabled,
                        )
                        let updated = AppConfig(
                            summarization: current.summarization, transcription: newTranscription,
                            storage: current.storage, translation: current.translation,
                            contextCache: current.contextCache, audioCapture: current.audioCapture,
                            uiTheme: current.uiTheme, privacyMode: current.privacyMode,
                            mcpConsentGranted: current.mcpConsentGranted,
                            mcpEndpoints: current.mcpEndpoints,
                            notionEnabled: current.notionEnabled,
                            obsidianVaultPath: current.obsidianVaultPath,
                        )
                        try await self.sharedConfigManager.save(updated)
                    } catch {
                        self.logger
                            .error("Failed to persist engine selection: \(String(reflecting: error), privacy: .public)")
                    }
                }
            }
        }
        archivePassEnabledObserver = NotificationCenter.default.addObserver(
            forName: .archivePassEnabledChanged, object: nil, queue: .main,
        ) { [weak self] note in
            guard let enabled = note.userInfo?["enabled"] as? Bool else { return }
            MainActor.assumeIsolated {
                guard let self else { return }
                self.archivePassEnabled = enabled
                Task { [weak self] in
                    guard let self else { return }
                    do {
                        let current = try await self.sharedConfigManager.load()
                        let newTranscription = TranscriptionConfig(
                            defaultEngine: current.transcription.defaultEngine,
                            fallbackEngine: current.transcription.fallbackEngine,
                            cleanupModelId: current.transcription.cleanupModelId,
                            archivePassEnabled: enabled,
                        )
                        let updated = AppConfig(
                            summarization: current.summarization, transcription: newTranscription,
                            storage: current.storage, translation: current.translation,
                            contextCache: current.contextCache, audioCapture: current.audioCapture,
                            uiTheme: current.uiTheme, privacyMode: current.privacyMode,
                            mcpConsentGranted: current.mcpConsentGranted,
                            mcpEndpoints: current.mcpEndpoints,
                            notionEnabled: current.notionEnabled,
                            obsidianVaultPath: current.obsidianVaultPath,
                        )
                        try await self.sharedConfigManager.save(updated)
                    } catch {
                        self.logger
                            .error("Failed to persist archive pass setting: \(String(reflecting: error), privacy: .public)")
                    }
                }
            }
        }
        recordingStartObserver = NotificationCenter.default.addObserver(
            forName: .recordingStarted, object: nil, queue: .main,
        ) { [weak self] _ in
            MainActor.assumeIsolated {
                guard let self else { return }
                self.applyPrivacyMode(self.currentPrivacyMode, isRecording: true)
            }
        }
        recordingStopObserver = NotificationCenter.default.addObserver(
            forName: .recordingStopped, object: nil, queue: .main,
        ) { [weak self] _ in
            MainActor.assumeIsolated {
                guard let self else { return }
                self.applyPrivacyMode(self.currentPrivacyMode, isRecording: false)
            }
        }
    }

    private func setupStatusBar(viewModel: MenuBarViewModel) {
        let item = NSStatusBar.system.statusItem(withLength: NSStatusItem.variableLength)
        item.button?.image = NSImage(systemSymbolName: "waveform", accessibilityDescription: "THE RECORD")
        item.button?.action = #selector(togglePopover)
        item.button?.target = self
        statusItem = item

        let pop = NSPopover()
        pop.contentSize = NSSize(width: 320, height: 400)
        pop.behavior = .transient
        pop.contentViewController = NSHostingController(rootView: MenuBarPopover(viewModel: viewModel))
        popover = pop
    }

    // MARK: - Privacy Mode

    private func applyPrivacyMode(_ mode: PrivacyMode, isRecording: Bool) {
        guard let window = NSApp.windows.first else { return }
        let protect: Bool = switch mode {
        case .off: false
        case .always: true
        case .meetings: isRecording
        }
        window.sharingType = protect ? .none : .readOnly
    }

    // MARK: - Toggle

    @objc private func togglePopover() {
        guard let button = statusItem?.button, let pop = popover else { return }
        if pop.isShown {
            pop.performClose(nil)
        } else {
            pop.show(relativeTo: button.bounds, of: button, preferredEdge: .minY)
        }
    }
}

